// ── Build a minimal AST with plain objects ───────────────────────

const Literal    = (value)        => ({ type: 'Literal',    value });
const Identifier = (name)         => ({ type: 'Identifier', name });
const BinaryExpr = (op, left, right) => ({
  type: 'BinaryExpression', operator: op, left, right
});
const ReturnStmt = (argument)     => ({ type: 'ReturnStatement', argument });
const BlockStmt  = (body)         => ({ type: 'BlockStatement',  body });
const FuncDecl   = (name, params, body) => ({
  type: 'FunctionDeclaration',
  id:     Identifier(name),
  params: params.map(Identifier),
  body:   BlockStmt(body)
});

// AST for:  function add(a, b) { return a + b; }
const ast = FuncDecl('add', ['a', 'b'], [
  ReturnStmt(BinaryExpr('+', Identifier('a'), Identifier('b')))
]);

// ── Generic depth-first walker ────────────────────────────────────
function walk(node, visitor) {
  if (!node || typeof node !== 'object') return;
  // Call enter handler if defined
  const handler = visitor[node.type];
  const enter = typeof handler === 'function' ? handler
              : typeof handler === 'object'   ? handler.enter
              : null;
  if (enter) enter(node);
  // Recurse into child nodes
  for (const key of Object.keys(node)) {
    const child = node[key];
    if (Array.isArray(child)) {
      child.forEach(c => { if (c && c.type) walk(c, visitor); });
    } else if (child && typeof child === 'object' && child.type) {
      walk(child, visitor);
    }
  }
  // Call exit handler if defined
  const exit = typeof handler === 'object' ? handler.exit : null;
  if (exit) exit(node);
}

// ── Visitor 1: collect every Identifier name ─────────────────────
const names = [];
walk(ast, {
  Identifier(node) { names.push(node.name); }
});
console.log('Identifiers:', names);
// Identifiers: [ 'add', 'a', 'b', 'a', 'b' ]

// ── Visitor 2: simple interpreter for numeric binary expressions ──
function evalNode(node, env) {
  switch (node.type) {
    case 'Literal':    return node.value;
    case 'Identifier': return env[node.name];
    case 'BinaryExpression': {
      const l = evalNode(node.left,  env);
      const r = evalNode(node.right, env);
      if (node.operator === '+') return l + r;
      if (node.operator === '-') return l - r;
      if (node.operator === '*') return l * r;
      if (node.operator === '/') return l / r;
      throw new Error(`Unknown operator: ${node.operator}`);
    }
    default: throw new Error(`Cannot evaluate: ${node.type}`);
  }
}

const returnExpr = ast.body.body[0].argument; // the `a + b` node
console.log('add(3, 7) =', evalNode(returnExpr, { a: 3, b: 7 })); // 10
console.log('add(10, 4) =', evalNode(returnExpr, { a: 10, b: 4 })); // 14

// ── Visitor 3: a linting rule — flag + used on non-string literals ─
const lintWarnings = [];
walk(ast, {
  BinaryExpression(node) {
    if (node.operator === '+' &&
        node.left.type  === 'Literal' && typeof node.left.value  === 'number' &&
        node.right.type === 'Literal' && typeof node.right.value === 'number') {
      lintWarnings.push('prefer-constant-folding: ' +
        `${node.left.value} + ${node.right.value} can be precomputed`);
    }
  }
});
console.log('Lint warnings:', lintWarnings); // [] — no constant literals here

// ── ESTree node shapes reference (no library needed to run) ──────

// const x = 42
const varDeclNode = {
  type: 'VariableDeclaration',
  kind: 'const',
  declarations: [{
    type: 'VariableDeclarator',
    id:   { type: 'Identifier', name: 'x' },
    init: { type: 'Literal', value: 42, raw: '42' }
  }]
};

// console.log('hello')
const callNode = {
  type: 'CallExpression',
  callee: {
    type: 'MemberExpression',
    object:   { type: 'Identifier', name: 'console' },
    property: { type: 'Identifier', name: 'log' },
    computed: false
  },
  arguments: [{ type: 'Literal', value: 'hello' }]
};

// (x) => x * 2  — concise arrow
const arrowNode = {
  type: 'ArrowFunctionExpression',
  params: [{ type: 'Identifier', name: 'x' }],
  body: {
    type: 'BinaryExpression', operator: '*',
    left:  { type: 'Identifier', name: 'x' },
    right: { type: 'Literal', value: 2 }
  },
  expression: true   // body is an expression, not a BlockStatement
};

console.log('varDecl kind:', varDeclNode.kind); // 'const'
console.log('call callee:', callNode.callee.object.name + '.' + callNode.callee.property.name);
// console.log
console.log('arrow is expression body?', arrowNode.expression); // true

// ── ESLint-style rule skeleton: no-console ───────────────────────
function makeNoConsoleRule(walk) {
  return {
    CallExpression(node) {
      const { callee } = node;
      if (
        callee.type === 'MemberExpression' &&
        callee.object.type === 'Identifier' &&
        callee.object.name === 'console'
      ) {
        const method = callee.property.name;
        console.warn(`[no-console] Unexpected console.${method}() call.`);
      }
    }
  };
}

// Simulated rule execution:
const noConsoleVisitor = makeNoConsoleRule();
noConsoleVisitor.CallExpression(callNode);
// [no-console] Unexpected console.log() call.

// ── Babel-style transform: arrow → function expression ───────────
// A Babel plugin visitor that replaces ArrowFunctionExpression
// with a FunctionExpression so older environments can run it.
const arrowToFunctionPlugin = {
  ArrowFunctionExpression(path) {
    // path.node is the ArrowFunctionExpression
    // In real Babel: path.replaceWith(t.functionExpression(...))
    console.log('Would transform arrow at params:',
      path.node.params.map(p => p.name).join(', '));
  }
};
// Simulating Babel path object:
arrowToFunctionPlugin.ArrowFunctionExpression({ node: arrowNode });
// Would transform arrow at params: x

sections.content:
A Babel plugin is a function that returns a visitor object. Babel's core traversal engine handles the rest. The full structure looks like:

```js
module.exports = function myPlugin({ types: t }) {
  return {
    visitor: {
      // Replace `x ** 2` (ExponentiationExpression) with `Math.pow(x, 2)`
      BinaryExpression(path) {
        if (path.node.operator !== '**') return;
        const { left, right } = path.node;
        path.replaceWith(
          t.callExpression(
            t.memberExpression(t.identifier('Math'), t.identifier('pow')),
            [left, right]
          )
        );
      }
    }
  };
};
```

The `t` (types) object is a collection of **builder functions** — `t.identifier('foo')` creates an `Identifier` node, `t.callExpression(callee, args)` creates a `CallExpression`, and so on. Using builders rather than raw object literals is safer because builders validate their arguments and fill in required fields with sensible defaults.

The `path` object wraps the current node and provides mutation methods:
- `path.replaceWith(newNode)` — swap this node for another
- `path.remove()` — delete this node from the tree
- `path.insertBefore(node)` — insert a new node before this one in its parent
- `path.skip()` — do not descend into children of this node
- `path.get('left')` — get a path object for the `left` child
- `path.scope` — the Babel scope API for variable analysis

This architecture means plugin authors never manage the traversal loop — they just declare interest in specific node types and mutate what they find. Babel composes multiple plugins by running all their visitors in a single traversal pass (for efficiency).

**Common real-world Babel transforms:**
- `@babel/plugin-transform-arrow-functions` — `ArrowFunctionExpression` → `FunctionExpression` with explicit `this` binding
- `@babel/plugin-transform-optional-chaining` — `MemberExpression` with `optional: true` → nested ternary checks
- `@babel/plugin-transform-nullish-coalescing-operator` — `LogicalExpression` with `??` operator → `!== null && !== undefined` check
